// Loads the IC-test catalogue (JSON, generated by TRL's private build_catalogue.py
// in trl-sharedlibs — only its OUTPUT ships here) and matches a component's
// "Technical name or value" to a test entry.
//
// The catalogue + vectors are BUNDLED next to the executable (resolved via
// AppContext.BaseDirectory), NOT seeded into the online-synced DataRoot — so the
// online sync's orphan-deletion never touches them. Match key is the technical
// name (NOT Part-number: board data has copy-paste errors there). UI-free.

using Handlers.DataHandling;
using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Text.Json;

namespace Handlers.IcTesting;

public static class IcTestCatalogue
{
    private static readonly object Gate = new();
    private static readonly JsonSerializerOptions Json = new() { PropertyNameCaseInsensitive = true };

    private static List<IcTestEntry>? _entries;
    private static Dictionary<string, IcTestEntry>? _byMatch;
    private static string? _vectorsDir;

    public static string DefaultCatalogueDir =>
        Path.Combine(DataManager.DataRoot, "Generic shared files", "MiniPro", "IC tests", "Catalogue");
//        Path.Combine(AppContext.BaseDirectory, "Assets", "MiniPro", "IC-Tests", "catalogue");

    /// <summary>Directory holding external vector files (e.g. the PLA's gzipped XML).</summary>
    public static string VectorsDir => _vectorsDir ?? Path.Combine(DataManager.DataRoot, "Generic shared files", "MiniPro", "IC tests", "Vectors");
//    public static string VectorsDir => _vectorsDir ?? Path.Combine(AppContext.BaseDirectory, "Assets", "MiniPro", "IC-Tests", "vectors");

    public static IReadOnlyList<IcTestEntry> Entries
    {
        get { EnsureLoaded(null); return _entries!; }
    }

    /// <summary>(Re)load the catalogue from <paramref name="dir"/> (or the bundled default).</summary>
    public static void Load(string? dir = null)
    {
        var catalogueDir = dir ?? DefaultCatalogueDir;
        var entries = new List<IcTestEntry>();
        if (Directory.Exists(catalogueDir))
        {
            foreach (var file in Directory.EnumerateFiles(catalogueDir, "*.json").OrderBy(f => f))
            {
                if (string.Equals(Path.GetFileName(file), "index.json", StringComparison.OrdinalIgnoreCase))
                    continue;
                try
                {
                    var entry = JsonSerializer.Deserialize<IcTestEntry>(File.ReadAllText(file), Json);
                    if (entry is not null && !string.IsNullOrWhiteSpace(entry.Id))
                        entries.Add(entry);
                }
                catch (JsonException)
                {
                    // A malformed entry must not take the whole catalogue down.
                }
            }
        }

        var index = new Dictionary<string, IcTestEntry>(StringComparer.OrdinalIgnoreCase);
        foreach (var e in entries)
            foreach (var m in e.Match)
            {
                var key = Normalize(m);
                if (key.Length > 0)
                    index.TryAdd(key, e);
            }

        lock (Gate)
        {
            _entries = entries;
            _byMatch = index;
            // Vectors sit beside the catalogue dir when an explicit dir is given (tests).
            _vectorsDir = dir is null ? null : Path.Combine(Path.GetDirectoryName(dir)!, "Vectors");
        }
    }

    /// <summary>The test entry for a component's technical name/value, or null.</summary>
    public static IcTestEntry? Lookup(string? technicalNameOrValue)
    {
        if (string.IsNullOrWhiteSpace(technicalNameOrValue))
            return null;
        EnsureLoaded(null);
        return _byMatch!.GetValueOrDefault(Normalize(technicalNameOrValue));
    }

    /// <summary>True when a component is an IC with a catalogue entry (gates the Test button).</summary>
    public static bool IsTestable(string? category, string? technicalNameOrValue) =>
        string.Equals(category?.Trim(), "IC", StringComparison.OrdinalIgnoreCase)
        && Lookup(technicalNameOrValue) is not null;

    private static void EnsureLoaded(string? dir)
    {
        if (_byMatch is null)
            lock (Gate)
                if (_byMatch is null)
                    Load(dir);
    }

    private static string Normalize(string s) => s.Trim().ToUpperInvariant();
}
